SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.NAME AS oblname, Имена_станций.ordnumb, Станции2016.YEAR, Станции2016.NUST, Станции2016.nr, Станции2016.E, Станции2016.EOTP, Станции2016.EURT, Станции2016.EUST, Станции2016.Q, Станции2016.TURT, Станции2016.TUST, Станции2016.B, Станции2016.GAZ, Доп_угли2016.gazpp, Станции2016.MAZUT, Станции2016.TORF, Станции2016.SLAN, Станции2016.PROCH, Станции2016.UGOL, Станции2016.DON, Станции2016.PODM, Станции2016.PECH, Доп_угли2016.intin, Доп_угли2016.vork, Станции2016.ARKT, Станции2016.KUZN, Доп_угли2016.kuzngd, Доп_угли2016.kuznt, Доп_угли2016.kuznss, Доп_угли2016.kuznun, Станции2016.URAL, Доп_угли2016.sver, Доп_угли2016.chel, Доп_угли2016.kizel, Станции2016.BASHK, Станции2016.KAZAH, Доп_угли2016.ekib, Доп_угли2016.maikub, Станции2016.KARAG, Станции2016.KAN, Доп_угли2016.nazar, Доп_угли2016.ibor, Доп_угли2016.berez, Доп_угли2016.per, Доп_угли2016.irbei, Доп_угли2016.kansk, Станции2016.TUNG, Доп_угли2016.jer, Доп_угли2016.karab, Станции2016.IRKUT, Доп_угли2016.azey, Доп_угли2016.mug, Доп_угли2016.cher, Станции2016.HAK, Станции2016.TUV, Станции2016.BUR, Доп_угли2016.gusin, Доп_угли2016.tugn, Доп_угли2016.okino, Станции2016.CHIT, Доп_угли2016.har, Доп_угли2016.urt, Доп_угли2016.tataur, Доп_угли2016.tarbag, Доп_угли2016.zab_kam, Станции2016.YAKUT, Доп_угли2016.neru, Доп_угли2016.zyryan, Доп_угли2016.pyak, Станции2016.AMUR, Доп_угли2016.rai, Доп_угли2016.erk, Станции2016.URG, Станции2016.USHUM, Станции2016.PRIM, Доп_угли2016.bikin, Доп_угли2016.razdol, Доп_угли2016.hankai, Станции2016.MAG, Станции2016.SAH, Станции2016.KAMCH, Станции2016.CHUKOT, Доп_угли2016.anad, Доп_угли2016.bering, Станции2016.QOTR, Станции2016.SNK, Станции2016.EWTP, Станции2016.NT, Станции2016.OBOR, Станции2016.VED, Станции2016.OBL, Станции2016.DEP, Станции2016.OES, Станции2016.ER, Станции2016.NUMB1120, Имена_станций.Ведомство AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group], Имена_станций.FO, Имена_станций.форэм, Имена_станций.GK, Станции2016.BE, имена_ГК.name AS namegk, имена_БЕ.name AS namebe, Города.Name AS Town, IIf([obor]=20 Or [obor]=90,"ГТУ",IIf([obor]=21 Or [obor]=91,"ПГУ",IIf([obor]=22,"Диз",IIf([obor]=23,"Дет","ПСУ")))) AS тип
FROM (((Имена_станций LEFT JOIN Города ON Имена_станций.codegor=Города.code) INNER JOIN (Имена_областей INNER JOIN (Имена_ОЭС INNER JOIN (Станции2016 LEFT JOIN Доп_угли2016 ON (Станции2016.YEAR=Доп_угли2016.YEAR) AND (Станции2016.NUMB1120=Доп_угли2016.NUMB1120)) ON Имена_ОЭС.oes=Станции2016.OES) ON Имена_областей.OBL=Станции2016.OBL) ON Имена_станций.NUMB=Станции2016.NUMB1120) LEFT JOIN имена_ГК ON Станции2016.GK=имена_ГК.code) LEFT JOIN имена_БЕ ON Станции2016.BE=имена_БЕ.code;
